{% for i in issues | reverse %}


  {{ site.title }} {{ i.label }} ({{ i.cutoff | date_long }})
  {{ site_url }}issues/{{ '%03d' | format(i.number) }}.html
  {{ site_url }}issues/{{ '%03d' | format(i.number) }}.html
  {{ (i.generated_at or i.cutoff) | rfc822 }}
  <p>{{ i.count }} papers.</p><ol>{% for a in i.articles | sort(attribute='ordinal') %}<li><a href="{{ a.link }}">{{ a.title | e }}</a> — {{ a.authors | authors_inline | e }}. <em>{{ a.venue | e }}</em>.{% if a.abstract %} {{ a.abstract | truncate_text(400) | e }}{% endif %}</li>{% endfor %}</ol>

{% endfor %}
